  // default remult
  __attribute__((__target__("default")))
  inline void remult(complex<float> const * const in1,
      complex<float> const * const in2, const int len,
      complex<float> * const out)
  {
    for(int i=0; i<len; ++i) out[i] = in1[i]*in2[i].real();
    return;
  }
  
