      re = _mm256_moveldup_ps(ld2); // [Br0,Br0,Br1,Br1,...,Br3,Br3]
      ld3 = _mm256_fmsubadd_ps(sh, im, ld3); // [Ai0*Bi0+Cr0,Ar0*Bi0-Ci0,...]
      ld1 = _mm256_fmsubadd_ps(ld1, re, ld3);// [Ar0*Br0+Ai0*Bi0+Cr0,...]
