        im = _mm256_mul_ps(sh, im);   // [-Ai0*Bi0,Ar0*Bi0,...,-Ai3*Bi3,Ar3*Bi3]
        ld1 = _mm256_fmsubadd_ps(re, ld1, im); // [Br0*Ar0-Bi0Ai0,-Br0*Ai0-Ar0*Bi0]
