        re = _mm256_moveldup_ps(ld4); // [Dr0,Dr0,Dr1,Dr1,...,Dr3,Dr3]
        im = _mm256_mul_ps(sh, im);   // [-Ci0*Di0,Cr0*Di0,...,-Ci3*Di3,Cr3*Di3]
