        sh = _mm512_unpacklo_ps(rc, rc); // [1/|B0|^2,1/|B0|^2,1/|B1|^2,...]
        rc = _mm512_unpackhi_ps(rc, rc); // [1/|D0|^2,1/|D0|^2,1/|D1|^2,...]
        ld1 = _mm512_mul_ps(ld1, sh); // (A*B)/|B|^2 == A/conj(B)
        ld3 = _mm512_mul_ps(ld3, rc); // (C*D)/|D|^2 == C/conj(D)
