        ld1 = _mm256_permutevar8x32_ps(ld1, p1); // [Q0,Q0,Q1,Q1,Q2,Q2,Q3,Q3]
        _mm256_maskstore_ps(reinterpret_cast<float *>(&out[i+4]), msk2, ld2);
