    hs = _mm_add_ps(hs, _mm_permute_ps(hs, 0x4e));
    // store both real and imaginary parts with one 8-byte store to avoid
    // instruction stall with certain compilers
    _mm_storel_pi(reinterpret_cast<__m64 *>(&out), hs);
