    {
      out.real(0.0f);
      out.imag(0.0f);
      return;
    }
    __m256 ld1, ld2, sh;
    __m256 sumr = _mm256_set1_ps(0.0f); // real part of dot-product
    __m256 sumi = sumr;                 // imaginary part of dot-product
    __m128 hs;  // horizontal sum to finish dot-product
