      im = _mm256_add_ps(_mm256_mul_ps(ar, bi), _mm256_mul_ps(ai, br));
      // |product|^2
      sc = _mm256_add_ps(_mm256_mul_ps(re, re), _mm256_mul_ps(im, im));
