        ld2 = _mm256_rsqrt_ps(ld1);   // [1/|A0|,1/|A1|,1/|B0|,1/|B1|,...]
        ld1 = _mm256_rcp_ps(ld2);     // [|A0|,|A1|,|B0|,|B1|,...]
