      im = _mm512_mul_ps(im, sc);
      _mm512_storeu_ps(reinterpret_cast<float *>(&out[i]),
          _mm512_unpacklo_ps(re, im));
      _mm512_storeu_ps(reinterpret_cast<float *>(&out[i+8]),
          _mm512_unpackhi_ps(re, im));
