      im = _mm256_shuffle_ps(ld1, ld2, 0xdd); // [Ai0,Ai1,Bi0,Bi1,...]
      ld1 = _mm256_fmadd_ps(re, re, _mm256_mul_ps(im, im)); // |in|^2
      ld1 = _mm256_permutevar8x32_ps(ld1, p1); // back in element order
