      ph = _mm256_maskload_ps(&in[i], _mm256_load_si256(
          reinterpret_cast<__m256i const *>(masks[n])));
      ph = _mm256_castpd_ps(_mm256_permute4x64_pd(_mm256_castps_pd(ph),
          0xd8));
